import{_ as e,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Vivienda y Protección Ambiental","description":"","frontmatter":{},"headers":[],"relativePath":"es/0039-住房与环境保障.md","filePath":"es/0039-住房与环境保障.md"}'),n={name:"es/0039-住房与环境保障.md"};function t(r,a,l,d,c,u){return i(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="vivienda-y-proteccion-ambiental" tabindex="-1">Vivienda y Protección Ambiental <a class="header-anchor" href="#vivienda-y-proteccion-ambiental" aria-label="Permalink to &quot;Vivienda y Protección Ambiental&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>39</td></tr><tr><td>Módulo</td><td>Tipos de Civilización y Sistemas Sociales</td></tr><tr><td>Palabras clave</td><td>Garantía de Vivienda, Protección Ambiental, Simbiosis Ecológica, Espacios Habitables, Desarrollo Sostenible</td></tr></tbody></table><h2 id="i-conceptos-fundamentales-de-la-vivienda-y-la-proteccion-ambiental" tabindex="-1">I. Conceptos Fundamentales de la Vivienda y la Protección Ambiental <a class="header-anchor" href="#i-conceptos-fundamentales-de-la-vivienda-y-la-proteccion-ambiental" aria-label="Permalink to &quot;I. Conceptos Fundamentales de la Vivienda y la Protección Ambiental&quot;">​</a></h2><p>&quot;Que cada residente tenga su vivienda&quot; es una cuestión vital básica que toda civilización debe afrontar. En la era del Sistema de Cultivo Depredador, la vivienda y la tierra estaban monopolizadas por unos pocos poderosos y sectas, y las masas de la base solían carecer de domicilio fijo, obligadas a cultivar y vivir en entornos hostiles. Más grave aún, el cultivo depredador causaba enormes daños al medio ambiente: las vetas espirituales eran sobreexplotadas, la ecología gravemente contaminada y los recursos planetarios consumidos de manera depredadora, convirtiendo muchos planetas antes habitables en tierras baldías.</p><p>Tras el establecimiento de la Civilización Simbiótica del Ancla, la garantía de vivienda y la protección ambiental se convirtieron en contenidos centrales de la construcción institucional social. El concepto fundamental de la vivienda y la protección ambiental puede resumirse en dieciséis caracteres: &quot;Una Vivienda para Cada Residente, Simbiosis Ecológica, Desarrollo Sostenible, Habitable para las Diez Mil Razas&quot;.</p><p>Los objetivos fundamentales de la vivienda y la protección ambiental incluyen:</p><ol><li><strong>Garantizar el derecho básico a la vivienda</strong>: asegurar que cada vida simbiótica obtenga una vivienda digna, segura y adecuada, y que los problemas de vivienda no afecten la supervivencia y la evolución</li><li><strong>Proteger el entorno ecológico</strong>: establecer un sistema completo de protección ambiental, mantener el equilibrio ecológico y evitar que las actividades de cultivo dañen el medio ambiente</li><li><strong>Construir espacios habitables</strong>: mediante la planificación científica y los medios tecnológicos, construir espacios habitables adecuados para el cultivo y la vida</li><li><strong>Realizar el desarrollo sostenible</strong>: mientras se satisfacen las necesidades de la generación actual, no perjudicar la capacidad de las generaciones futuras para satisfacer sus necesidades, logrando el uso sostenible de los recursos y el medio ambiente</li><li><strong>Promover la habitabilidad de las Diez Mil Razas</strong>: la construcción de viviendas y medio ambiente considera plenamente las características fisiológicas y los hábitos de vida de las distintas razas, garantizando que las Diez Mil Razas puedan vivir cómodamente</li></ol><h2 id="ii-el-sistema-de-garantia-de-vivienda" tabindex="-1">II. El Sistema de Garantía de Vivienda <a class="header-anchor" href="#ii-el-sistema-de-garantia-de-vivienda" aria-label="Permalink to &quot;II. El Sistema de Garantía de Vivienda&quot;">​</a></h2><p>El sistema de garantía de vivienda de la civilización simbiótica sigue los principios de &quot;garantizar lo básico, promover la mejora, múltiples canales y sostenibilidad&quot;, construyendo un sistema de suministro de vivienda multinivel:</p><h3 id="_2-1-los-tres-niveles-del-suministro-de-vivienda" tabindex="-1">2.1 Los Tres Niveles del Suministro de Vivienda <a class="header-anchor" href="#_2-1-los-tres-niveles-del-suministro-de-vivienda" aria-label="Permalink to &quot;2.1 Los Tres Niveles del Suministro de Vivienda&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Destinatarios</th><th>Tipo de Vivienda</th><th>Alquiler/Precio</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Vivienda Garantizada</td><td>Grupos de bajos ingresos, cultivadores recién iniciados</td><td>Apartamentos básicos de cultivo, dormitorios colectivos</td><td>Gratuita o alquiler extremadamente bajo</td></tr><tr><td>Segundo nivel</td><td>Vivienda Mejorada</td><td>Grupos de ingresos medios, cultivadores intermedios</td><td>Residencias estándar de cultivo, apartamentos familiares</td><td>Precio de costo o alquiler bajo</td></tr><tr><td>Tercer nivel</td><td>Vivienda Comercial</td><td>Grupos de altos ingresos, cultivadores avanzados</td><td>Residencias de cultivo de alto nivel, moradas de cueva independientes</td><td>Precio de mercado</td></tr></tbody></table><h3 id="_2-2-el-sistema-de-vivienda-garantizada" tabindex="-1">2.2 El Sistema de Vivienda Garantizada <a class="header-anchor" href="#_2-2-el-sistema-de-vivienda-garantizada" aria-label="Permalink to &quot;2.2 El Sistema de Vivienda Garantizada&quot;">​</a></h3><p>La vivienda garantizada es el núcleo del sistema de garantía de vivienda, asegurando el derecho básico a la vivienda de cada vida simbiótica:</p><ul><li><strong>Apartamentos básicos de cultivo</strong>: pequeños apartamentos para cultivadores recién iniciados e individuos solteros, equipados con instalaciones básicas de cultivo, con alquiler extremadamente bajo o gratuito</li><li><strong>Dormitorios colectivos</strong>: alojamiento colectivo para discípulos de sectas, estudiantes y trabajadores colectivos, con espacios compartidos de cultivo</li><li><strong>Vivienda garantizada familiar</strong>: viviendas completas para familias de bajos ingresos, de tamaño moderado y equipamiento completo</li><li><strong>Vivienda garantizada especial</strong>: viviendas adaptadas para vidas discapacitadas, razas especiales, cultivadores mayores y otros grupos especiales</li></ul><p>La solicitud y asignación de la vivienda garantizada sigue los principios de &quot;transparencia, equidad y justicia&quot;, con solicitudes y verificaciones realizadas a través de la red simbiótica, y resultados de asignación públicos y transparentes.</p><h3 id="_2-3-el-sistema-de-vivienda-mejorada" tabindex="-1">2.3 El Sistema de Vivienda Mejorada <a class="header-anchor" href="#_2-3-el-sistema-de-vivienda-mejorada" aria-label="Permalink to &quot;2.3 El Sistema de Vivienda Mejorada&quot;">​</a></h3><p>La vivienda mejorada está orientada a grupos de ingresos medios con cierta capacidad económica, proporcionada a precio de costo o alquiler reducido:</p><ul><li><strong>Residencias estándar de cultivo</strong>: viviendas completas con sala de cultivo independiente, adecuadas para individuos y familias con cierta base de cultivo</li><li><strong>Apartamentos familiares</strong>: apartamentos de tamaño medio adecuados para familias, con espacios de actividades infantiles y zonas de cultivo familiar</li><li><strong>Apartamentos para talentos</strong>: viviendas preferenciales para talentos de alto nivel incorporados y personal técnico profesional</li></ul><p>La oferta de vivienda mejorada se ajusta dinámicamente según la demanda, garantizando que los grupos de ingresos medios puedan obtener viviendas adecuadas a costos razonables.</p><h3 id="_2-4-el-sistema-de-vivienda-comercial" tabindex="-1">2.4 El Sistema de Vivienda Comercial <a class="header-anchor" href="#_2-4-el-sistema-de-vivienda-comercial" aria-label="Permalink to &quot;2.4 El Sistema de Vivienda Comercial&quot;">​</a></h3><p>La vivienda comercial está orientada a grupos de altos ingresos y se proporciona a precios de mercado:</p><ul><li><strong>Residencias de cultivo de alto nivel</strong>: residencias de lujo equipadas con instalaciones avanzadas de cultivo</li><li><strong>Moradas de cueva independientes</strong>: moradas de cueva de cultivo con espacio independiente y suministro de energía</li><li><strong>Residencias personalizadas</strong>: residencias especiales diseñadas según las necesidades individuales</li></ul><p>Las transacciones de vivienda comercial siguen las reglas del mercado, pero el gobierno regula mediante impuestos sobre la propiedad, gestión de tierras y otros medios, evitando aumentos excesivos de precios y la especulación inmobiliaria.</p><h3 id="_2-5-equipamiento-de-espacios-de-cultivo" tabindex="-1">2.5 Equipamiento de Espacios de Cultivo <a class="header-anchor" href="#_2-5-equipamiento-de-espacios-de-cultivo" aria-label="Permalink to &quot;2.5 Equipamiento de Espacios de Cultivo&quot;">​</a></h3><p>En la civilización simbiótica, la vivienda no es solo un espacio de vida, sino también un espacio de cultivo. Cada vivienda está equipada con instalaciones de cultivo correspondientes según las necesidades de cultivo de los residentes:</p><ul><li><strong>Zona básica de cultivo</strong>: cada vivienda cuenta con una zona básica de cultivo, equipada con interfaces básicas de acceso a energía</li><li><strong>Suministro de energía</strong>: suministro de energía estable para las viviendas a través de la Red del Ancla, satisfaciendo las necesidades de cultivo</li><li><strong>Aislamiento acústico y energético</strong>: las zonas de cultivo cuentan con instalaciones de aislamiento acústico y protección energética, evitando que el cultivo perturbe a otros</li><li><strong>Espacios públicos de cultivo</strong>: las comunidades cuentan con espacios compartidos como salones públicos de cultivo y salas de equipos de cultivo</li></ul><h2 id="iii-el-sistema-de-proteccion-ambiental" tabindex="-1">III. El Sistema de Protección Ambiental <a class="header-anchor" href="#iii-el-sistema-de-proteccion-ambiental" aria-label="Permalink to &quot;III. El Sistema de Protección Ambiental&quot;">​</a></h2><p>El sistema de protección ambiental de la civilización simbiótica sigue los principios de &quot;prevención primaria, tratamiento integral, restauración ecológica y uso sostenible&quot;, construyendo un marco integral de protección ambiental:</p><h3 id="_3-1-estandares-ambientales-y-supervision" tabindex="-1">3.1 Estándares Ambientales y Supervisión <a class="header-anchor" href="#_3-1-estandares-ambientales-y-supervision" aria-label="Permalink to &quot;3.1 Estándares Ambientales y Supervisión&quot;">​</a></h3><p>La civilización simbiótica ha formulado estrictos estándares ambientales, regulando el impacto ambiental de las actividades de cultivo y producción:</p><ul><li><strong>Estándares de emisión de energía</strong>: límites estrictos a las emisiones de energía generadas durante el cultivo y la producción</li><li><strong>Estándares de extracción de recursos</strong>: regulación de la extracción de vetas espirituales, minerales, recursos biológicos, etc., evitando la sobreexplotación</li><li><strong>Líneas rojas de protección ecológica</strong>: delimitar líneas rojas de protección ecológica, dentro de las cuales se prohíbe cualquier actividad destructiva</li><li><strong>Evaluación de impacto ambiental</strong>: los grandes proyectos de cultivo y construcción deben someterse a evaluación de impacto ambiental</li></ul><p>La supervisión de la protección ambiental es responsabilidad de instituciones de supervisión ambiental dedicadas, que monitorean la calidad ambiental en tiempo real a través de la red simbiótica e imponen severas sanciones a las actividades ilegales.</p><h3 id="_3-2-tecnologias-de-tratamiento-de-la-contaminacion" tabindex="-1">3.2 Tecnologías de Tratamiento de la Contaminación <a class="header-anchor" href="#_3-2-tecnologias-de-tratamiento-de-la-contaminacion" aria-label="Permalink to &quot;3.2 Tecnologías de Tratamiento de la Contaminación&quot;">​</a></h3><p>La civilización simbiótica ha desarrollado tecnologías avanzadas de tratamiento de la contaminación:</p><ul><li><strong>Tratamiento de la contaminación energética</strong>: mediante filtración de energía, conversión de energía y otras tecnologías, tratar la contaminación energética generada por las actividades de cultivo</li><li><strong>Tratamiento de la contaminación material</strong>: mediante biorremediación, tratamiento químico, purificación física y otras tecnologías, tratar la contaminación material</li><li><strong>Tratamiento de la contaminación por leyes</strong>: mediante desprendimiento de leyes, neutralización de leyes y otras tecnologías, tratar la contaminación ambiental causada por la erosión de leyes</li><li><strong>Tecnologías de restauración ecológica</strong>: mediante el Sistema de Circulación Vital y las tecnologías de ingeniería ecológica, restaurar los ecosistemas dañados</li></ul><h3 id="_3-3-uso-sostenible-de-los-recursos" tabindex="-1">3.3 Uso Sostenible de los Recursos <a class="header-anchor" href="#_3-3-uso-sostenible-de-los-recursos" aria-label="Permalink to &quot;3.3 Uso Sostenible de los Recursos&quot;">​</a></h3><p>La civilización simbiótica enfatiza el uso sostenible de los recursos y se opone al desarrollo depredador:</p><ul><li><strong>Cuotas de extracción de recursos</strong>: implementar sistemas de cuotas de extracción para los recursos no renovables, garantizando el uso a largo plazo de los recursos</li><li><strong>Reciclaje de recursos</strong>: desarrollar vigorosamente tecnologías de reciclaje de recursos, mejorando la eficiencia de uso de los recursos</li><li><strong>Desarrollo de energías renovables</strong>: desarrollar activamente energías renovables como la solar, eólica, hidráulica y la energía de campos energéticos</li><li><strong>Investigación de recursos alternativos</strong>: investigar sustitutos de los recursos escasos, reduciendo la dependencia de los recursos escasos</li></ul><h3 id="_3-4-proteccion-y-restauracion-ecologica" tabindex="-1">3.4 Protección y Restauración Ecológica <a class="header-anchor" href="#_3-4-proteccion-y-restauracion-ecologica" aria-label="Permalink to &quot;3.4 Protección y Restauración Ecológica&quot;">​</a></h3><p>La civilización simbiótica concede gran importancia a la protección y restauración ecológica:</p><ul><li><strong>Reservas naturales</strong>: establecer reservas naturales a todos los niveles, protegiendo especies raras y ecosistemas prístinos</li><li><strong>Proyectos de restauración ecológica</strong>: restaurar los ecosistemas ya dañados, restableciendo el equilibrio ecológico</li><li><strong>Programas de protección de especies</strong>: proteger y criar especies en peligro de extinción, evitando su desaparición</li><li><strong>Mecanismo de compensación ecológica</strong>: compensar a las regiones y grupos que sufren pérdidas debido a la protección ecológica</li></ul><h2 id="iv-construccion-de-espacios-habitables" tabindex="-1">IV. Construcción de Espacios Habitables <a class="header-anchor" href="#iv-construccion-de-espacios-habitables" aria-label="Permalink to &quot;IV. Construcción de Espacios Habitables&quot;">​</a></h2><p>Sobre la base de la vivienda y la protección ambiental, la civilización simbiótica promueve vigorosamente la construcción de espacios habitables:</p><h3 id="_4-1-planificacion-urbana" tabindex="-1">4.1 Planificación Urbana <a class="header-anchor" href="#_4-1-planificacion-urbana" aria-label="Permalink to &quot;4.1 Planificación Urbana&quot;">​</a></h3><p>La planificación urbana de la civilización simbiótica sigue los principios de &quot;compacta, verde, inteligente y humana&quot;:</p><ul><li><strong>Disposición compacta</strong>: las ciudades adoptan disposiciones compactas, reduciendo la ocupación de suelo y el consumo de energía del transporte</li><li><strong>Espacios verdes</strong>: las ciudades conservan amplios espacios verdes como zonas ajardinadas, parques y humedales</li><li><strong>Gestión inteligente</strong>: mediante la Red del Ancla y las tecnologías inteligentes, lograr la gestión inteligente de las ciudades</li><li><strong>Atención humana</strong>: la planificación urbana considera plenamente las necesidades de los grupos de diferentes razas, edades y capacidades</li></ul><h3 id="_4-2-construccion-de-comunidades-de-cultivo" tabindex="-1">4.2 Construcción de Comunidades de Cultivo <a class="header-anchor" href="#_4-2-construccion-de-comunidades-de-cultivo" aria-label="Permalink to &quot;4.2 Construcción de Comunidades de Cultivo&quot;">​</a></h3><p>La civilización simbiótica construye vigorosamente comunidades de cultivo que integran residencia, cultivo y servicios:</p><ul><li><strong>Centros comunitarios de cultivo</strong>: cada comunidad cuenta con un centro de cultivo, que ofrece espacios públicos de cultivo y orientación de cultivo</li><li><strong>Centros de servicios comunitarios</strong>: ofrecen servicios integrales como salud, educación, comercio y entretenimiento</li><li><strong>Espacios verdes comunitarios</strong>: las comunidades conservan amplios espacios verdes y de ocio</li><li><strong>Cultura comunitaria</strong>: cultivar la cultura comunitaria, fortaleciendo el sentido de pertenencia y la cohesión de los residentes</li></ul><h3 id="_4-3-espacios-habitables-transplanar" tabindex="-1">4.3 Espacios Habitables Transplanar <a class="header-anchor" href="#_4-3-espacios-habitables-transplanar" aria-label="Permalink to &quot;4.3 Espacios Habitables Transplanar&quot;">​</a></h3><p>Con el avance de la exploración transplanar, la civilización simbiótica ha comenzado a construir espacios habitables en otros planos:</p><ul><li><strong>Transformación de habitabilidad de planos</strong>: transformar planos adecuados para hacerlos habitables, construyendo nuevos espacios residenciales y de cultivo</li><li><strong>Migración ecológica</strong>: migrar de manera planificada a la población desde planos con recursos tensionados hacia planos habitables recién desarrollados</li><li><strong>Vivienda transplanar</strong>: proporcionar garantía de vivienda transplanar a los cultivadores que viajan frecuentemente entre planos</li></ul><h2 id="v-diferencias-en-los-modelos-de-vivienda-y-medio-ambiente-de-los-cinco-tipos-de-civilizacion" tabindex="-1">V. Diferencias en los Modelos de Vivienda y Medio Ambiente de los Cinco Tipos de Civilización <a class="header-anchor" href="#v-diferencias-en-los-modelos-de-vivienda-y-medio-ambiente-de-los-cinco-tipos-de-civilizacion" aria-label="Permalink to &quot;V. Diferencias en los Modelos de Vivienda y Medio Ambiente de los Cinco Tipos de Civilización&quot;">​</a></h2><p>Los cinco tipos de civilización simbiótica tienen sus propias características en los modelos de vivienda y medio ambiente:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Características del Modelo de Vivienda</th><th>Características del Modelo Ambiental</th></tr></thead><tbody><tr><td>Tipo Intensivo de Asia Oriental</td><td>Alta densidad, intensivo, dormitorios colectivos como forma principal</td><td>Supervisión estricta, gobernanza eficiente, restauración rápida</td></tr><tr><td>Tipo Nórdico de Bienestar</td><td>Alta garantía, alta calidad, personalizado</td><td>Altos estándares, alta inversión, ecología primero</td></tr><tr><td>Tipo Pluralista Norteamericano</td><td>Mercantilizado, diversificado, baja densidad</td><td>Gobernanza de mercado, impulsado por tecnología, protección de recursos</td></tr><tr><td>Tipo Social Europeo Continental</td><td>Vivienda social, vivienda cooperativa, asignación equilibrada</td><td>Participación asociativa, gobernanza deliberativa, desarrollo sostenible</td></tr><tr><td>Tipo de Desarrollo y Alcance</td><td>Garantía primero, construcción rápida, mejora gradual</td><td>Desarrollo y protección a la vez, gobernanza focalizada</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La vivienda y la protección ambiental son la &quot;piedra angular del bienestar&quot; y la &quot;barrera ecológica&quot; de la Civilización Simbiótica del Ancla. A través del sistema de garantía de vivienda multinivel, el sistema integral de protección ambiental y la construcción científica de espacios habitables, la civilización simbiótica ha logrado los objetivos de &quot;Una Vivienda para Cada Residente, Simbiosis Ecológica, Desarrollo Sostenible, Habitable para las Diez Mil Razas&quot;. La garantía de vivienda permite a cada vida simbiótica cultivar con tranquilidad, y la protección ambiental sienta la base ecológica para el desarrollo a largo plazo de la civilización. Ambas se complementan, sosteniendo conjuntamente el avance de las Diez Mil Razas y el desarrollo sostenible de la civilización simbiótica.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>45-住房保障法 (Ley de Garantía de Vivienda)</li><li>46-环境保护法 (Ley de Protección Ambiental)</li><li>32-北欧福利型文明 (Civilización de Bienestar Nórdico)</li></ul>',59)])])}const v=e(n,[["render",t]]);export{p as __pageData,v as default};
